#include <cstring>
struct Heap {std::map<uint32_t,std::vector<uint32_t>> blocks;uint32_t next=0x3000000,dd=0,vt=0,surface=0,surfaceVT=0,releases=0;ClawSceneDisplayContext* display=nullptr;ClawSceneLifecycleContext* lifecycle=nullptr;};
Heap* activeHeap=nullptr;
uint32_t allocation(Heap&h,uint32_t bytes){uint32_t t=h.next;h.next+=(bytes+15)&~15;h.blocks[t]=std::vector<uint32_t>((bytes+3)/4,0xa5a5a5a5);return t;}
uint32_t* lookup(void*v,uint32_t t,uint32_t n){auto&h=*static_cast<Heap*>(v);if(t%4)return nullptr;auto i=h.blocks.upper_bound(t);if(i==h.blocks.begin())return nullptr;--i;uint64_t offset=uint64_t(t)-i->first;if(offset+uint64_t(n)*4>i->second.size()*4)return nullptr;return i->second.data()+offset/4;}
void put(Heap&h,uint32_t t,uint32_t x){auto*p=lookup(&h,t,1);assert(p);*p=x;}
uint32_t lifecycleDependency(ClawSceneLifecycleContext*,const ClawSceneLifecycleCall*,void*);
uint32_t dependency(ClawSceneDisplayContext*c,const ClawSceneDisplayCall*q,void*){auto&h=*activeHeap;switch(q->function){
case 0x4f63ec:return allocation(h,q->arguments[0]);case 0x4f6428:if(q->arguments[0])assert(h.blocks.erase(q->arguments[0])==1);return 0;
case 0x546850:put(h,q->arguments[1],h.dd);return 0;
case 0x700050:case 0x700020:case 0x700054:case 0x70004c:return 0;
case 0x700008:case 0x710008:++h.releases;return 0;
case 0x70002c:assert(*lookup(&h,q->arguments[1],79)==316);return 0;
case 0x700030:assert(q->localMask==2);q->buffers[0][21]=8;return 0;
case 0x700018:put(h,q->arguments[2],h.surface);return 0;
case 0x710030:assert(q->localMask==6&&q->bufferCount==2);q->buffers[1][0]=h.surface;return 0;
case 0x710058:{auto*p=lookup(&h,q->arguments[1],27);assert(p);std::memset(p,0,108);p[0]=108;p[2]=480;p[3]=640;p[4]=640;p[21]=8;return 0;}
default:{uint32_t out=0;assert(claw_scene_display_entry(q->function,q->receiver,q->arguments,q->argumentCount,c,dependency,nullptr,&out));return out;}}
}
uint32_t graphicsDependency(ClawGraphicsManagerLifecycleContext*,const ClawGraphicsManagerLifecycleCall*q,void*){auto&h=*activeHeap;ClawSceneDisplayCall e{};e.function=q->function;e.receiver=q->receiver;e.argumentCount=q->argumentCount;std::memcpy(e.arguments,q->arguments,sizeof e.arguments);e.localMask=q->localMask;e.bufferCount=q->bufferCount;for(unsigned i=0;i<2;++i){e.buffers[i]=q->buffers[i];e.bufferBytes[i]=q->bufferBytes[i];}return dependency(h.display,&e,nullptr);}
uint32_t lifecycleDependency(ClawSceneLifecycleContext*c,const ClawSceneLifecycleCall*q,void*){ClawSceneDisplayCall e{};e.function=q->function;e.receiver=q->receiver;e.argumentCount=q->argumentCount;std::memcpy(e.arguments,q->arguments,sizeof e.arguments);e.localMask=q->localMask;e.bufferCount=q->bufferCount;assert(e.bufferCount<=2);for(unsigned i=0;i<e.bufferCount;++i){e.buffers[i]=q->buffers[i];e.bufferBytes[i]=q->bufferBytes[i];}return dependency(c->display,&e,nullptr);}
void emptyMap(Heap&h,uint32_t t,bool stringMap){for(uint32_t i=0;i<28;i+=4)put(h,t+i,0);put(h,t,stringMap?0x510054:0x5105c4);put(h,t+8,17);put(h,t+24,10);}
void keyMap(Heap&h,uint32_t t){uint32_t buckets=allocation(h,20),block=allocation(h,52);put(h,block,0);for(uint32_t i=0;i<20;i+=4)put(h,buckets+i,0);for(uint32_t i=0;i<3;++i){uint32_t node=block+4+16*i,key=allocation(h,16);put(h,key,1);put(h,key+4,3);put(h,key+8,3);put(h,key+12,0x00636261);put(h,node,i==2?0:node+16);put(h,node+4,2);put(h,node+8,key+12);put(h,node+12,0);}put(h,buckets+8,block+4);put(h,t+4,buckets);put(h,t+8,5);put(h,t+12,3);put(h,t+20,block);}
void tables(Heap&h){h.blocks[0x513c68]={0,0x4cf760,0,0,0,0x4cf730,0,0x4ca8b0,0x4cf750,0x4ca6f0};h.blocks[0x5138d8]={0,0x4cabe0,0,0,0,0x4cacb0,0,0x4caca0,0,0x4cac00,0,0x4d5510};h.blocks[0x50e8e4]={0,0x45fe40,0,0,0,0x4cacb0,0,0x4d4160,0,0x4d4000};h.blocks[0x513690]={0x4bc5f0,0x4b91f0,0x4b9150,0x4b9180,0x4b9540,0x4bb000,0,0,0x4b9380,0,0,0x4bf970};h.blocks[0x5136c0]={0x4bc810,0x4b91f0,0x4bfbd0,0x4b9180,0x4b9540,0x4bb000,0,0,0x4b9380,0x4bfb80};h.blocks[0x513588]={0x4bb060,0x4b91f0,0x4b9150,0x4b9180,0x4b9540,0x4bb000,0,0,0x4b9380};h.blocks[0x541378]=std::vector<uint32_t>(5);h.blocks[0x52e1b8]={0xffffffff,0,0,0};h.blocks[0x52e1c8]={0x52e1b8,0x52e1c4};h.blocks[0x54316c]={1,7};h.blocks[0x541178]=std::vector<uint32_t>(101);h.blocks[0x513b88]=std::vector<uint32_t>(23);h.blocks[0x513b88][22]=0x4d0240;h.blocks[0x513b88][1]=0x4cf160;h.blocks[0x513b60]={0,0x4cf940};h.blocks[0x513b28]={0,0x4cf0a0};h.blocks[0x513ad8]={0,0x4cf9d0};h.blocks[0x513b00]={0,0x4cf800};}
int main(){for(uint32_t i=0;i<64;++i){Heap h;activeHeap=&h;tables(h);ClawGraphicsManagerLifecycleGlobals globals{};ClawGameImageGlobals image{};ClawGraphicsManagerLifecycleContext graphics{};ClawSceneDisplayContext c{};h.display=&c;c.scene.context=&h;c.scene.lookup=lookup;c.graphics=&graphics;c.image=&image;graphics.scene=c.scene;graphics.globals=&globals;
 uint32_t manager=allocation(h,2180),parent=allocation(h,60),holder=allocation(h,28);h.dd=allocation(h,4);h.vt=allocation(h,0x60);h.surface=allocation(h,4);h.surfaceVT=allocation(h,0x84);put(h,h.dd,h.vt);put(h,h.surface,h.surfaceVT);for(uint32_t slot:{8u,0x18u,0x20u,0x2cu,0x30u,0x4cu,0x50u,0x54u})put(h,h.vt+slot,0x700000+slot);for(uint32_t slot:{8u,0x30u,0x58u})put(h,h.surfaceVT+slot,0x710000+slot);globals.sharedDevice=i%2?h.dd:0;uint32_t out=0;assert(claw_graphics_manager_lifecycle_entry(0x4bc120,manager,nullptr,0,&graphics,graphicsDependency,nullptr,&out));assert(claw_graphics_manager_lifecycle_entry(0x4bc0e0,0,nullptr,0,&graphics,graphicsDependency,nullptr,&out));std::memset(lookup(&h,parent,15),0,60);put(h,parent+4,holder);put(h,parent+28,manager);put(h,parent+48,0x12345);put(h,holder,0x513c68);put(h,holder+12,parent);for(uint32_t offset:{16u,20u,24u})put(h,holder+offset,0);
 ClawSceneLifecycleContext life{};life.scene=c.scene;life.display=&c;life.graphics=&graphics;life.image=&image;h.lifecycle=&life;
 uint32_t imageController=allocation(h,44),logicController=allocation(h,44),paletteController=allocation(h,104),animationController=allocation(h,44),soundController=allocation(h,52);
 for(auto pair:{std::pair<uint32_t,uint32_t>{imageController,0x513b88},{logicController,0x513b60},{paletteController,0x513b28},{animationController,0x513ad8},{soundController,0x513b00}}){put(h,pair.first,pair.second);put(h,pair.first+4,0);put(h,pair.first+8,0);put(h,pair.first+12,parent);emptyMap(h,pair.first+16,pair.first==animationController||pair.first==soundController);keyMap(h,pair.first+16);}emptyMap(h,paletteController+44,false);emptyMap(h,paletteController+72,false);put(h,paletteController+100,7);put(h,soundController+44,manager);
 put(h,parent+16,imageController);put(h,parent+20,logicController);put(h,parent+24,paletteController);put(h,parent+40,soundController);put(h,parent+44,animationController);
 uint32_t args[]={640,480,8,i%2};assert(claw_scene_display_entry(0x4ca6f0,holder,args,4,&c,dependency,nullptr,&out)&&out==1);assert(claw_scene_lifecycle_entry(0x4ceef0,parent,nullptr,0,&life,lifecycleDependency,nullptr,&out));assert(!globals.cooperativeHolder);assert(h.releases==((i%2)?2u:3u));for(uint32_t offset=4;offset<=44;offset+=4)assert(*lookup(&h,parent+offset,1)==0);assert(claw_scene_lifecycle_entry(0x4ce9c0,parent,nullptr,0,&life,lifecycleDependency,nullptr,&out));uint32_t deleting=1;assert(claw_scene_lifecycle_entry(0x4ce9a0,parent,&deleting,1,&life,lifecycleDependency,nullptr,&out)&&out==parent);assert(!h.blocks.count(parent)&&!h.blocks.count(manager));assert(c.scene.context==&h&&graphics.scene.context==&h);}}
